class Solution {
  public int minFlips(String s) {
    int n = s.length(), ones = 0;
    for (int i = 0; i < n; i++) if (s.charAt(i) == '1') ones++;
    if (n == 1) return 0;
    int best = Math.max(0, ones - 1);
    best = Math.min(best, n - ones);
    int middleOnes = ones - (s.charAt(0) == '1' ? 1 : 0) - (s.charAt(n - 1) == '1' ? 1 : 0);
    best =
        Math.min(
            best, (s.charAt(0) == '0' ? 1 : 0) + (s.charAt(n - 1) == '0' ? 1 : 0) + middleOnes);
    return best;
  }
}
